INSERT INTO `v1_b075dd1e0090b3e307364ce4bf3210ef9ae7948b43081d7a8200160d46ecb597` VALUES ("もうすぐ、みなさまに\nお会いできるのですね。\n胸が高鳴ってしまいます……\n", 321, 1, 1, 0, 1, 40011, 125801, "リリ", 2, 24001);
INSERT INTO `v1_b075dd1e0090b3e307364ce4bf3210ef9ae7948b43081d7a8200160d46ecb597` VALUES ("初めまして、クリアです♪\nみなさんと一緒に冒険するの\nとっても楽しみにしてます", 322, 1, 1, 0, 2, 40011, 126001, "クリア", 2, 24001);
INSERT INTO `v1_b075dd1e0090b3e307364ce4bf3210ef9ae7948b43081d7a8200160d46ecb597` VALUES ("んーと。\nこれ、あげる。\nはい", 323, 1, 1, 0, 3, 40011, 126101, "プレシア", 2, 24001);
INSERT INTO `v1_b075dd1e0090b3e307364ce4bf3210ef9ae7948b43081d7a8200160d46ecb597` VALUES ("あらためまして……\n【アルターメイデン】の\nギルドマスター、リリと申します", 324, 1, 2, 0, 4, 40011, 125801, "リリ", 2, 24001);
INSERT INTO `v1_b075dd1e0090b3e307364ce4bf3210ef9ae7948b43081d7a8200160d46ecb597` VALUES ("こんにちは、お兄さん♪\n【アルターメイデン】の\nクリアです", 325, 1, 2, 0, 5, 40011, 126001, "クリア", 2, 24001);
INSERT INTO `v1_b075dd1e0090b3e307364ce4bf3210ef9ae7948b43081d7a8200160d46ecb597` VALUES ("お兄。\nきてくれて、うれしい", 326, 1, 2, 0, 6, 40011, 126101, "プレシア", 2, 24001);
